#include "stdlib/lapack/base/dlantr.h"
#include "stdlib/constants/float64/nan.h"

/**
* Computes a norm of a triangular or trapezoidal matrix.
*
* @param layout   storage layout
* @param norm     norm type: M, 1/O, I, or F/E (case-insensitive)
* @param uplo     upper or lower trapezoidal storage
* @param diag     unit or non-unit diagonal
* @param M        number of rows
* @param N        number of columns
* @param A        input matrix
* @param LDA      leading dimension
* @param work     M-element scratch array for the infinity norm
* @return         norm (NaN for invalid options or dimensions)
*/
double API_SUFFIX(c_dlantr)( const LAPACK_LAYOUT layout, const char norm, const LAPACK_UPLO uplo, const LAPACK_DIAGONAL diag, const LAPACK_INT M, const LAPACK_INT N, const double *A, const LAPACK_INT LDA, double *work ) {
	LAPACK_INT sa1;
	LAPACK_INT sa2;

	if ( layout != LAPACK_ROW_MAJOR && layout != LAPACK_COL_MAJOR ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	if ( LDA < 1 || ( layout == LAPACK_ROW_MAJOR && LDA < N ) || ( layout == LAPACK_COL_MAJOR && LDA < M ) ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	if ( layout == LAPACK_COL_MAJOR ) {
		sa1 = 1;
		sa2 = LDA;
	} else {
		sa1 = LDA;
		sa2 = 1;
	}
	return API_SUFFIX(c_dlantr_ndarray)( norm, uplo, diag, M, N, A, sa1, sa2, 0, work, 1, 0 );
}
